// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Reentrance} from "../src/Reentrance.sol";

contract InvMutTest is Test {
    Reentrance c;
    function setUp() public { c = new Reentrance(); }
    function testFuzz_property(address u, address v, uint256 amountU, uint256 amountV) public {
        vm.assume(u != v);
        vm.assume(u != address(0));
        vm.assume(v != address(0));
        vm.assume(amountU <= type(uint256).max / 2);
        vm.assume(amountV <= type(uint256).max / 2);

        vm.deal(u, amountU);
        vm.prank(u);
        c.addToBalance{value: amountU}();

        vm.deal(v, amountV);
        vm.prank(v);
        c.addToBalance{value: amountV}();

        uint256 balanceOfV = c.getBalance(v);
        assertTrue(balanceOfV == amountV);
    }
}
